select ip,count(*) as count from t_link_access_logs
where gid = #{gid} and full_short_url = #{fullShortUrl}
  and create_time between #{start} and #{end} and del_flag = 0
group by ip order by count desc limit 5;

select user,CASE WHEN MIN(create_time) BETWEEN #{start} AND #{end} THEN '新访客' ELSE '老访客' END as uvType
from t_link_access_logs
         where gid = #{gid} and full_short_url = #{fullShortUrl}
         and user in

            #{user}

group by user
